    #[test]
    fn bab_lp_lowerings_apply_typed_chain_probe_opts() {
        let mut model = Model::new();
        let x = model.add_binary_col();
        let objective = [(x.0, 1.0)];
        let lower = |opts: &SolveOpts| {
            let mut lp = FloatLp::from_model(&model, &objective, Sense::Minimize)
                .expect("small model lowers");
            apply_bab_lp_opts(&mut lp, opts);
            lp
        };

        let default = lower(&SolveOpts::new());
        let disabled = lower(&SolveOpts::new().with_chain_distress_probe_iters(Some(0)));
        let configured = lower(
            &SolveOpts::new()
                .with_chain_distress_probe_iters(Some(8_192))
                .with_range_logical_triangular_crash(),
        );

        assert_eq!(default.chain_distress_probe_iters_override(), None);
        assert!(!default.range_logical_triangular_crash_requested());
        assert_eq!(
            disabled.chain_distress_probe_iters_override(),
            Some(0),
            "an explicit zero must reach Bab LPs rather than fall back globally"
        );
        assert_eq!(
            configured.chain_distress_probe_iters_override(),
            Some(8_192)
        );
        assert!(configured.range_logical_triangular_crash_requested());
    }

    /// The serial shared-prefix entry promises one root, including on an
    /// infeasible symmetric model whose requested tree certificate would make
    /// the ordinary symmetry lane re-solve the model.
    ///
    /// The negative control deliberately recreates the old mode
    /// (`no_sym=false`). `rows` symmetry both poisons its first literal capture
    /// and increments `SYM_ROWS_TOTAL`, and the certificate harvest therefore
    /// enters and prepares a root exactly twice. The production entry must
    /// suppress symmetry before its first root: one entry, one preparation,
    /// zero rows, and a tree that verifies directly against the caller model.
    #[test]
    fn serial_shared_prefix_has_one_root_even_when_symmetry_would_retry_for_a_tree() {
        use std::sync::atomic::Ordering::Relaxed;

        let _env_lock = lock_env();
        // B39b: rows-mode symmetry + no heuristic share ride the engine
        // profile chained onto this test's opts below.

        // The LP has the unique symmetric point (1/2, 1/2, 1/2), while every
        // binary assignment is contradictory. It cannot be discharged by a
        // root Farkas ray, so the returned evidence must be a real split tree.
        let mut model = Model::new();
        let x = model.add_binary_col();
        let y = model.add_binary_col();
        let z = model.add_binary_col();
        model.add_row(1.0, 1.0, &[(x, 1.0), (y, 1.0)]);
        model.add_row(1.0, 1.0, &[(y, 1.0), (z, 1.0)]);
        model.add_row(1.0, 1.0, &[(x, 1.0), (z, 1.0)]);
        let prefix = [x, y, z];
        let opts = SolveOpts::new()
            .with_tree_cert_leaves(64)
            .with_require_certificates(true)
            .with_engine(
                crate::EngineEconomics::new()
                    .with_heur_share(0.0)
                    .with_sym_mode(1)
                    .expect("rows in domain"),
            );

        // `solve_milp_in` is a lower-level entry that does not activate the
        // engine profile itself; this direct-call test activates it for the
        // whole scope.
        let _tuned = crate::tune::activate_caller(opts.engine().profile());
        let entries_before = SHARED_PREFIX_SOLVE_ENTRIES_TOTAL.load(Relaxed);
        let roots_before = SHARED_PREFIX_ROOT_PREPARATIONS_TOTAL.load(Relaxed);
        let rows_before = SYM_ROWS_TOTAL.load(Relaxed);
        let old_mode = solve_milp_in(
            &model,
            &opts,
            SearchMode {
                no_sym: false,
                ..SearchMode::FULL
            },
            None,
            &[],
            &[],
            &prefix,
        );
        let old_tree = match old_mode {
            Outcome::Infeasible {
                tree_cert: Some(tree),
                ..
            } => tree,
            other => panic!("old symmetry mode must settle with harvested evidence, got {other:?}"),
        };
        old_tree
            .verify(&model)
            .expect("the negative-control retry must harvest caller-frame evidence");
        assert!(
            SYM_ROWS_TOTAL.load(Relaxed) > rows_before,
            "negative control never engaged symmetry, so it proves nothing"
        );
        assert_eq!(
            SHARED_PREFIX_SOLVE_ENTRIES_TOTAL.load(Relaxed) - entries_before,
            2,
            "the old mode must expose the hidden symmetry certificate retry"
        );
        assert_eq!(
            SHARED_PREFIX_ROOT_PREPARATIONS_TOTAL.load(Relaxed) - roots_before,
            2,
            "each old-mode solve entry must prepare its own root"
        );

        let entries_before = SHARED_PREFIX_SOLVE_ENTRIES_TOTAL.load(Relaxed);
        let roots_before = SHARED_PREFIX_ROOT_PREPARATIONS_TOTAL.load(Relaxed);
        let rows_before = SYM_ROWS_TOTAL.load(Relaxed);
        let outcome = solve_milp_shared_binary_prefix(&model, &opts, &prefix, &[], &[]);
        let tree = match outcome {
            Outcome::Infeasible {
                tree_cert: Some(tree),
                ..
            } => tree,
            other => panic!("one-root serial prefix must return tree evidence, got {other:?}"),
        };
        tree.verify(&model)
            .expect("the one-root tree must verify in the caller frame");
        assert_eq!(
            SHARED_PREFIX_SOLVE_ENTRIES_TOTAL.load(Relaxed) - entries_before,
            1,
            "the admitted serial prefix must enter exactly one top-level solve"
        );
        assert_eq!(
            SHARED_PREFIX_ROOT_PREPARATIONS_TOTAL.load(Relaxed) - roots_before,
            1,
            "the admitted serial prefix must prepare exactly one root"
        );
        assert_eq!(
            SYM_ROWS_TOTAL.load(Relaxed),
            rows_before,
            "serial prefix symmetry must be dark from the first root"
        );
    }

    /// The reduced-frame certificate is not evidence in the caller's frame, and
    /// the singleton postsolve must not hand it over as if it were. It used to
    /// drop it (and this test asserted the resulting
    /// `CertificateUnavailable`); it now LIFTS it, and the obligation is the
    /// same one stated the other way round: what comes out must verify against
    /// the model the caller handed in.
    #[test]
    fn singleton_postsolve_lifts_the_reduced_optimality_certificate() {
        let _env_lock = lock_env();
        let _singleton_sub = crate::tune::activate_caller(crate::tune::Profile::EMPTY.with(
            crate::tune::Knob::SingletonSub,
            crate::tune::Setting::Flag(true),
        ));

        // Eliminating free x from x + z = 1 folds the whole objective into
        // const_delta = 1, leaving a zero-objective reduced model whose empty
        // optimality certificate is valid THERE and false here.
        let mut model = Model::new();
        let z = model.add_binary_col();
        let x = model.add_col(f64::NEG_INFINITY, f64::INFINITY);
        model.add_row(1.0, 1.0, &[(x, 1.0), (z, 1.0)]);
        model.set_objective(&[(x, 1.0), (z, 1.0)], Sense::Minimize);

        // NEGATIVE CONTROL, and the reason the old behaviour was to strip: the
        // reduced model's own certificate claims a bound of 0 for this
        // objective, and the true optimum is 1.
        let reduced_frame_claim = crate::cert::OptimalityCertificate {
            sense: Sense::Minimize,
            objective: Vec::new(),
            bound: BigRational::zero(),
            multipliers: Vec::new(),
        };
        assert_eq!(
            reduced_frame_claim.verify(&model),
            Ok(()),
            "an EMPTY certificate verifies anywhere — which is exactly why it \
             must not be relabelled as evidence for the caller's objective"
        );

        let opts = SolveOpts::new()
            .with_tree_cert_leaves(0)
            .with_require_certificates(true);
        let mut session = crate::BabSession::new(model.clone(), &opts).expect("valid model");
        match session.check().expect("solve") {
            Outcome::Optimal { value, cert, .. } => {
                assert_eq!(value, BigRational::from_integer(1.into()));
                let cert = cert.expect("the lift must produce caller-frame evidence");
                assert_eq!(
                    cert.verify(&model),
                    Ok(()),
                    "the lifted certificate must verify against the CALLER's model"
                );
                assert_eq!(
                    cert.bound,
                    BigRational::from_integer(1.into()),
                    "the bound must MEET the reported optimum, not the reduced model's 0"
                );
                assert_eq!(
                    cert.objective,
                    vec![
                        (0, BigRational::from_integer(1.into())),
                        (1, BigRational::from_integer(1.into())),
                    ],
                    "and it must name the CALLER's objective"
                );
            }
            other => panic!("expected Optimal with lifted evidence, got {other:?}"),
        }
    }

    /// **THE DECOUPLING'S EVIDENCE OBLIGATION, end to end, on DEFAULT OPTIONS.**
    ///
    /// This is the test the whole change has to pass. `100x₀ + 101x₁ + 102x₂ =
    /// 1000` over `[0,4]³ ∩ ℤ³` is INFEASIBLE — writing `s = x₀+x₁+x₂` gives
    /// `100s + x₁ + 2x₂ = 1000`, so `s = 10` forces `x₁ = x₂ = 0` and `x₀ = 10`
    /// outside the box, and `s ≤ 9` cannot make up 100 from `x₁ + 2x₂ ≤ 12` — but
    /// `(10,0,0)` is an integer solution of the equality, so `hnf_particular`
    /// succeeds and the kernel reformulation FIRES. Its LP relaxation is feasible
    /// (`x = 1000/303` on every column), so the proof is a real branch tree and
    /// not a root refutation.
    ///
    /// Before the decoupling this model took the unreduced path, because
    /// `SolveOpts::new()` arms capture; now it takes the reduced one, whose tree
    /// is about `z` columns and cannot be lifted. The verdict is settled either
    /// way. What must not change is the EVIDENCE, and there is only one way to
    /// get it: `harvest_tree_cert_by_resolve` re-solves this model — the caller's
    /// own — and hands back the tree that solve captured. So this test fails the
    /// moment the harvest stops doing its job, which is exactly the property a
    /// sabotage check needs it to have.
    #[test]
    fn a_reduced_infeasible_solve_still_ships_a_verifying_tree_certificate() {
        // A READER of the environment, not a writer — see `solve_lock` in
        // `lattice::kernel_reform_tests`. A sibling test's `with_max_nodes`
        // leaking into this solve would stop the tree before it closed and turn
        // the missing certificate into a false failure.
        let _env_lock = lock_env();
        let mut m = Model::new();
        let cols: Vec<Col> = (0..3).map(|_| m.add_int_col(0.0, 4.0)).collect();
        m.add_row(
            1000.0,
            1000.0,
            &[(cols[0], 100.0), (cols[1], 101.0), (cols[2], 102.0)],
        );
        m.set_objective(&[(cols[0], 1.0)], Sense::Minimize);
        assert!(
            crate::lattice::reformulate_kernel(&m).is_some(),
            "the fixture must actually take the reduced path, or this proves nothing"
        );

        let opts = SolveOpts::new().with_time_limit(Duration::from_secs(30));
        assert!(
            opts.tree_cert_leaves > 0,
            "the default must still ARM capture — that default is what the decoupling \
             exists to stop charging for"
        );
        match solve_milp(&m, &opts) {
            Outcome::Infeasible { tree_cert, .. } => {
                let tree_cert = tree_cert
                    .expect("the harvest must buy the artifact the reduced frame could not lift");
                assert_eq!(
                    tree_cert.verify(&m),
                    Ok(()),
                    "and it must verify against the model the CALLER handed in"
                );
            }
            other => panic!("expected Infeasible with a tree certificate, got {other:?}"),
        }
    }

    /// The kill switch restores the OLD coupling, and the observable is `ej`.
    ///
    /// With `EngineEconomics::with_certificate_decoupling(false)` the kernel gate collapses back to
    /// `opts.tree_cert_leaves == 0`, which `SolveOpts::new()` does not satisfy —
    /// so the reformulation is skipped and `ej` goes back to stock branch and
    /// bound, where it is MEASURED at 235,008 nodes / 28.9 s with the dual bound
    /// pinned at 1 and no proof. The reformulated model proves in 3.
    ///
    /// The separation is therefore FOUR ORDERS OF MAGNITUDE IN NODES, and the
    /// test reads it as nodes rather than as seconds: `with_max_nodes` bounds
    /// both arms deterministically, so a loaded box cannot move the answer and
    /// the environment stays mutated for milliseconds instead of for a whole
    /// wall-clock budget. That matters beyond this test — every solve in this
    /// binary reads the environment, and a knob left set across a long solve is
    /// inherited by whatever else is running (see `solve_lock` in
    /// `lattice::kernel_reform_tests` for the leak that motivated the rule).
    #[test]
    fn the_kill_switch_puts_ej_back_behind_the_capture_gate() {
        let _env_lock = lock_env();
        let mut m = Model::new();
        let x0 = m.add_int_col(1.0, f64::INFINITY);
        let x1 = m.add_int_col(0.0, f64::INFINITY);
        let x2 = m.add_int_col(0.0, f64::INFINITY);
        m.add_row(0.0, 0.0, &[(x0, 31013.0), (x1, -41014.0), (x2, -51015.0)]);
        m.set_objective(&[(x0, 1.0)], Sense::Minimize);
        let opts = SolveOpts::new()
            .with_time_limit(Duration::from_secs(30))
            .with_engine(crate::EngineEconomics::new().with_max_nodes(1000));

        let opts_off = opts.clone().with_engine(
            crate::EngineEconomics::new()
                .with_max_nodes(1000)
                .with_certificate_decoupling(false),
        );
        {
            let _tuned = crate::tune::activate_caller(opts_off.engine().profile());
            assert!(
                !cert_decouple_enabled(),
                "the switch must be read where the gate reads it"
            );
        }
        assert!(
            !matches!(solve_milp(&m, &opts_off), Outcome::Optimal { .. }),
            "the old arm must NOT prove ej in 1,000 nodes — if it does, the \
             reformulation is still running and the switch is not a kill switch"
        );

        assert!(cert_decouple_enabled());
        match solve_milp(&m, &opts) {
            Outcome::Optimal { value, .. } => {
                assert_eq!(value, BigRational::from_integer(25508.into()));
            }
            other => panic!("the decoupled default must prove ej 25508, got {other:?}"),
        }
    }

    /// The reserve is a hold-back for an artifact; when the artifact becomes
    /// impossible the hold-back must go back to the search, all the way back —
    /// `deadline` AND the `reserved_deadline` the leaf pull-back would otherwise
    /// re-narrow onto.
    #[test]
    fn a_dead_capture_gives_the_finalize_reserve_back() {
        let now = Instant::now();
        let full = now + Duration::from_secs(30);
        let reserve = Duration::from_secs(5);
        let floor = Duration::from_millis(200);
        let fresh = || {
            (
                Some((full, reserve, floor)),
                Some(full - reserve),
                Some(full - reserve),
            )
        };

        // ARMED: a capture that can still produce a certificate keeps its budget.
        let (mut params, mut deadline, mut reserved) = fresh();
        assert!(!release_finalize_reserve(
            true,
            &mut params,
            &mut deadline,
            &mut reserved,
            Some(full)
        ));
        assert_eq!(params, Some((full, reserve, floor)));
        assert_eq!(deadline, Some(full - reserve));
        assert_eq!(reserved, Some(full - reserve));

        // POISONED: the whole hold-back comes back, and `reserved_deadline` with it —
        // otherwise the next integral leaf pulls the search straight back to `d - reserve`.
        let (mut params, mut deadline, mut reserved) = fresh();
        assert!(release_finalize_reserve(
            false,
            &mut params,
            &mut deadline,
            &mut reserved,
            Some(full)
        ));
        assert_eq!(params, None);
        assert_eq!(deadline, Some(full));
        assert_eq!(
            reserved,
            Some(full),
            "the leaf pull-back must not re-narrow onto a reserve nobody is waiting for"
        );

        // ONE-WAY: releasing twice is a no-op, so nothing can oscillate the deadline.
        assert!(!release_finalize_reserve(
            false,
            &mut params,
            &mut deadline,
            &mut reserved,
            Some(full)
        ));
        assert_eq!(deadline, Some(full));
    }

    /// The MARKED-MARGIN replay still runs on the slice it was reserved — that lane owns
    /// a proof slice explicitly, so shortening/lengthening it changes what the live
    /// preview and the terminal replay split between them.
    #[test]
    fn margin_replay_runs_on_its_reserve_and_never_past_the_caller_deadline() {
        let now = Instant::now();
        let reserve = Duration::from_secs(5);

        assert_eq!(
            finalize_deadline(Some(now + Duration::from_secs(30)), Some(reserve), now),
            Some(now + reserve)
        );
        // A search that ran to its own deadline leaves exactly the hold-back, so the cap
        // is slack and the historical behaviour is byte-identical.
        assert_eq!(
            finalize_deadline(Some(now + Duration::from_secs(1)), Some(reserve), now),
            Some(now + Duration::from_secs(1)),
            "the cap may only shorten the replay, never extend it past the caller"
        );
        // No reserve was ever carved (disarmed capture, or a budget too small to split):
        // the replay keeps the caller deadline it always had.
        assert_eq!(
            finalize_deadline(Some(now + Duration::from_secs(30)), None, now),
            Some(now + Duration::from_secs(30))
        );
        // An unbounded caller stays unbounded.
        assert_eq!(finalize_deadline(None, None, now), None);
    }

    /// THE ORDINARY TERMINAL FINALIZE GETS THE CALLER'S WALL, NOT THE RESERVE.
    ///
    /// The regression this pins: `W1_unsat_v16_c39_000008` (the downstream optimization consumer's captured W1 corpus)
    /// holds a 244-leaf tree that finalizes SUCCESSFULLY in 41.3 s, and the reserve-sized
    /// ceiling — 5 s, no matter how much of the caller's budget was left — cut it off at
    /// leaf 11 and shipped `evidence infeasible NONE`. The reserve is not gone: it is
    /// handed to `TreeCapture::finalize` as the PER-LEAF exact-rim slice, which is what
    /// actually bounded misc05inf (there the whole finalize was one rim solve).
    #[test]
    fn terminal_finalize_gets_the_callers_wall_not_the_reserve() {
        let now = Instant::now();
        let far = now + Duration::from_secs(120);
        assert_eq!(
            terminal_finalize_deadline(Some(far)),
            Some(far),
            "a search that finished early must not forfeit the budget the caller granted \
             for the artifact that budget was granted to produce"
        );
        // An unbounded caller stays unbounded, exactly as before.
        assert_eq!(terminal_finalize_deadline(None), None);
    }

    #[test]
    fn marked_margin_preview_uses_search_cutoff_then_terminal_gets_reserve() {
        let reserve = Duration::from_millis(200);
        let search = Instant::now() + Duration::from_millis(500);
        let full = search + reserve;
        let t0 = full
            .checked_sub(Duration::from_secs(1))
            .expect("the synthetic one-second lifecycle fits the monotonic clock");

        assert_eq!(full, t0 + Duration::from_secs(1));
        assert_eq!(
            search,
            full.checked_sub(reserve).expect("reserve fits"),
            "the active live-preview cutoff is exactly the reserved search cutoff"
        );
        assert!(live_margin_preview_enabled(true, Some(reserve), true));
        assert!(
            !live_margin_preview_enabled(true, None, true),
            "a finite caller clock without an actually carved reserve stays terminal-only"
        );
        assert!(!live_margin_preview_enabled(false, Some(reserve), true));
        assert!(!live_margin_preview_enabled(true, Some(reserve), false));

        // Inject a deterministic preview decline: two open regions do not fit
        // this clone's one-leaf budget. The real capture must survive, and a
        // later root restart/refinement can still use the terminal proof slice.
        let mut model = Model::new();
        let x = model.add_binary_col();
        model.add_row(1.0, f64::INFINITY, &[(x, 1.0)]);
        model.add_row(f64::NEG_INFINITY, 0.0, &[(x, 1.0)]);
        let mut capture = crate::tree_cert::TreeCapture::new(1);
        let root = capture.root();
        let _ = capture.split(root, x.index(), 0.0);
        let active_search_deadline = Some(search);
        assert!(capture
            .preview_margin_cover(&model, active_search_deadline)
            .is_none());
        assert!(
            capture.is_armed(),
            "preview failure must preserve the real capture"
        );

        capture.reset();
        let terminal_deadline = finalize_deadline(Some(full), Some(reserve), search);
        assert_eq!(
            terminal_deadline,
            Some(full),
            "when search reaches its reserved cutoff, terminal finalize gets the full reserve"
        );
        let cert = capture
            .finalize_margin_cover(&model, terminal_deadline)
            .expect("the preserved real capture succeeds during the terminal slice");
        cert.verify(&model)
            .expect("terminal authority verifies against the original model");
    }

    #[test]
    fn node_warm_deadline_never_exceeds_outer_deadline() {
        let now = Instant::now();
        let outer = now + Duration::from_millis(20);
        let opts = SolveOpts::new().with_node_warm_time_limit(Some(Duration::from_millis(200)));

        assert_eq!(
            node_warm_deadline(opts.node_warm_time_limit, now, Some(outer)),
            Some(outer)
        );
        assert_eq!(
            node_warm_deadline(None, now, Some(outer)),
            Some(outer),
            "a cold attempt must ignore the warm-only cap"
        );
    }

    #[test]
    fn node_warm_deadline_uses_shorter_typed_cap() {
        let now = Instant::now();
        let cap = Duration::from_millis(20);
        let outer = now + Duration::from_millis(200);
        let opts = SolveOpts::new().with_node_warm_time_limit(Some(cap));

        assert_eq!(
            node_warm_deadline(opts.node_warm_time_limit, now, Some(outer)),
            Some(now + cap)
        );
        assert_eq!(
            node_warm_deadline(opts.node_warm_time_limit, now, None),
            Some(now + cap)
        );
    }

    #[test]
    fn node_warm_deadline_handles_instant_overflow_without_extending_outer() {
        let now = Instant::now();
        assert!(
            now.checked_add(Duration::MAX).is_none(),
            "Duration::MAX must exceed this platform's Instant range"
        );
        let outer = now + Duration::from_millis(20);
        let opts = SolveOpts::new().with_node_warm_time_limit(Some(Duration::MAX));

        assert_eq!(
            node_warm_deadline(opts.node_warm_time_limit, now, Some(outer)),
            Some(outer)
        );
        assert_eq!(
            node_warm_deadline(opts.node_warm_time_limit, now, None),
            None,
            "an unrepresentable cap must behave as uncapped, not panic"
        );
    }

    /// The top-level MILP call site must pass an already-expired caller
    /// deadline into the parity device unchanged.  This rank-2/nullity-1
    /// lights-out system would otherwise produce an exact optimum.
    #[test]
    fn parity_call_site_honours_an_expired_deadline() {
        let mut m = Model::new();
        let x0 = m.add_binary_col();
        let x1 = m.add_binary_col();
        let x2 = m.add_binary_col();
        let y0 = m.add_int_col(0.0, f64::INFINITY);
        let y1 = m.add_int_col(0.0, f64::INFINITY);
        m.add_row(0.0, 0.0, &[(x0, 1.0), (x1, 1.0), (y0, -2.0)]);
        m.add_row(-1.0, -1.0, &[(x1, 1.0), (x2, 1.0), (y1, -2.0)]);
        m.set_objective(&[(x0, 1.0), (x1, 1.0), (x2, 1.0)], Sense::Minimize);

        let expired_at = Instant::now()
            .checked_sub(Duration::from_secs(1))
            .expect("the monotonic clock must be at least one second old");
        let opts = SolveOpts::new().with_deadline(expired_at);
        assert!(matches!(
            solve_milp(&m, &opts),
            Outcome::Unknown {
                reason: UnknownReason::Timeout
            }
        ));
    }

    #[test]
    fn branch_hints_normalize_in_caller_column_space() {
        let mut m = Model::new();
        let x = m.add_binary_col();
        let y = m.add_binary_col();
        let fixed = m.add_binary_col();
        let continuous = m.add_col(0.0, 1.0);
        let general_integer = m.add_int_col(0.0, 2.0);
        m.fix_col(fixed, 0.0);

        let hints = [Col(10_000), continuous, general_integer, fixed, y, y, x];
        assert_eq!(
            usable_branch_hints(&m, &hints),
            vec![y, x],
            "stale, non-binary, fixed, and duplicate advice must be ignored"
        );
    }

    #[test]
    fn root_probe_shortlist_is_ordered_root_only_and_falls_back_when_dead() {
        let candidates = [
            (0usize, 0.25, 4.0),
            (1usize, 0.50, 3.0),
            (2usize, 0.75, 2.0),
        ];
        assert_eq!(
            root_probe_candidates(true, &candidates, &[Col(2), Col(0)]),
            Some(vec![candidates[2], candidates[0]]),
            "the caller's shortlist order must own the bounded probe pool"
        );
        assert_eq!(
            root_probe_candidates(false, &candidates, &[Col(2)]),
            None,
            "deeper nodes must retain the historical pool"
        );
        assert_eq!(
            root_probe_candidates(true, &candidates, &[Col(99)]),
            None,
            "an all-dead shortlist must fall back to the historical pool"
        );
    }

    #[test]
    fn root_shortlist_breaks_only_equal_measured_scores() {
        let equal = [(0usize, 0.25, 0.0), (1usize, 0.50, 0.0)];
        let ranks = root_shortlist_branch_ranks(2, &[equal[0]], None);
        let picked = equal
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, Some(&ranks)))
            .expect("candidate");
        assert_eq!(
            picked.0, 0,
            "zero-objective reliability ties must prefer the advised root candidate"
        );

        let measured = [(0usize, 0.25, 0.0), (1usize, 0.50, 1.0)];
        let picked = measured
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, Some(&ranks)))
            .expect("candidate");
        assert_eq!(
            picked.0, 1,
            "a stronger measured score outside the shortlist must still win"
        );
    }

    #[test]
    fn exact_amo_inequality_never_enters_the_legacy_gub_path() {
        let mut model = Model::new();
        for _ in 0..GUB_MIN_ROWS {
            let x0 = model.add_binary_col();
            let x1 = model.add_binary_col();
            model.add_row(f64::NEG_INFINITY, 1.0, &[(x0, 1.0), (x1, 1.0)]);
        }

        assert!(
            set_partition_supports(&model).is_none(),
            "even threshold-many packing inequalities must not re-enter the overlapping equality-GUB cover"
        );
    }

    #[test]
    fn amo_multiway_is_opt_in_and_its_kill_switch_is_identity() {
        let _env_lock = lock_env();

        let mut model = Model::new();
        let x0 = model.add_binary_col();
        let x1 = model.add_binary_col();
        model.add_row(f64::NEG_INFINITY, 1.0, &[(x0, 1.0), (x1, 1.0)]);
        let rows = crate::cardinality_branch::unit_amo_rows(&model);
        assert_eq!(rows.len(), 1, "the exact AMO recognizer must fire");

        let values = [0.5, 0.5];
        let lower = [0.0, 0.0];
        let upper = [1.0, 1.0];
        {
            let armed = amo_multiway_branch_on(!rows.is_empty(), false);
            assert!(!armed, "the production default must be byte-identity off");
            assert!(
                planned_amo_multiway_split(armed, &rows, &values, &lower, &upper).is_none(),
                "recognition alone must not suppress probes or create children"
            );
        }
        {
            let _off = crate::tune::activate_caller(crate::tune::Profile::EMPTY.with(
                crate::tune::Knob::AmoMultiway,
                crate::tune::Setting::Flag(false),
            ));
            assert!(!amo_multiway_branch_on(!rows.is_empty(), false));
        }
        {
            let _on = crate::tune::activate_caller(crate::tune::Profile::EMPTY.with(
                crate::tune::Knob::AmoMultiway,
                crate::tune::Setting::Flag(true),
            ));
            let armed = amo_multiway_branch_on(!rows.is_empty(), false);
            assert!(armed);
            assert!(planned_amo_multiway_split(armed, &rows, &values, &lower, &upper).is_some());
            assert!(
                !amo_multiway_branch_on(!rows.is_empty(), true),
                "dynamic orbitopes must fail closed even when explicitly armed"
            );
        }
    }

    #[test]
    fn amo_multiway_children_fix_and_seed_the_whole_support_and_charge_memory() {
        use std::collections::{BTreeSet, BinaryHeap};

        let parent = Node {
            depth: 0,
            fixes: None,
            sym_seq: None,
            bound: None,
            bkey: f64::NAN,
            cover: None,
            warm: None,
            from_branch: None,
            structural_seeds: None,
            raw_bound: None,
            cap: crate::tree_cert::UNTRACKED,
            prepared: None,
        };
        let split = crate::cardinality_branch::AmoMultiwaySplit {
            row: 9,
            open: vec![0, 1, 2],
            one_order: vec![2, 0, 1],
        };
        let lower = [0.0; 3];
        let upper = [1.0; 3];
        let mut stack = BinaryHeap::new();
        let mut dive = Vec::new();
        let mut open_bytes = 0usize;
        push_amo_multiway_children(
            &mut stack,
            &mut dive,
            &parent,
            &split,
            &lower,
            None,
            None,
            None,
            false,
            &mut open_bytes,
            None,
            3,
        );

        assert_eq!(dive.len(), 1, "the LP-favoured member continues the dive");
        let mut preferred_lower = Vec::new();
        let mut preferred_upper = Vec::new();
        materialise_into(
            &lower,
            &upper,
            &dive[0].fixes,
            &mut preferred_lower,
            &mut preferred_upper,
        );
        assert_eq!(preferred_lower, vec![0.0, 0.0, 1.0]);
        assert_eq!(preferred_upper, vec![0.0, 0.0, 1.0]);

        let children: Vec<&Node> = dive.iter().chain(stack.iter()).collect();
        assert_eq!(children.len(), 4, "three active cases plus all-zero");
        assert_eq!(
            open_bytes,
            children
                .iter()
                .map(|child| node_bytes(child, 3))
                .sum::<usize>(),
            "every retained multiway child must be charged exactly once"
        );
        let mut assignments = BTreeSet::new();
        for child in children {
            assert_eq!(
                child.structural_seeds.as_deref(),
                Some(split.open.as_slice()),
                "all changed bounds must seed exact propagation"
            );
            let mut child_lower = Vec::new();
            let mut child_upper = Vec::new();
            materialise_into(
                &lower,
                &upper,
                &child.fixes,
                &mut child_lower,
                &mut child_upper,
            );
            assert_eq!(child_lower, child_upper, "every support member is fixed");
            assert!(
                child_lower.iter().filter(|&&value| value == 1.0).count() <= 1,
                "an AMO child cannot activate two members"
            );
            assert!(assignments.insert(
                child_lower
                    .into_iter()
                    .map(|value| u8::from(value == 1.0))
                    .collect::<Vec<_>>(),
            ));
        }
        let expected: BTreeSet<Vec<u8>> =
            BTreeSet::from([vec![0, 0, 0], vec![0, 0, 1], vec![0, 1, 0], vec![1, 0, 0]]);
        assert_eq!(assignments, expected);
    }

    #[test]
    fn dynamic_orbitope_state_exclusively_owns_structural_branching() {
        assert!(dynamic_orbitope_blocks_gub("orbital", true, true));
        assert!(
            !dynamic_orbitope_blocks_gub("orbital", false, true),
            "the static orbitope lane has no cloned dynamic sequence hazard"
        );
        assert!(
            !dynamic_orbitope_blocks_gub("orbital", true, false),
            "a requested but unassembled dynamic lane has no state to corrupt"
        );
        assert!(
            !dynamic_orbitope_blocks_gub("rows", true, true),
            "static symmetry-breaking rows consume the per-node machinery"
        );
    }

    #[test]
    fn conflict_cliques_require_exact_at_most_one_rows() {
        let _env_lock = lock_env();
        let _clique_branching = crate::tune::activate_caller(crate::tune::Profile::EMPTY.with(
            crate::tune::Knob::GubClique,
            crate::tune::Setting::Flag(true),
        ));
        // B29: the GUB arming default needs no setting (the old `=1` export
        // was vacuous — identical to unset); only the typed opt-out disables.
        assert!(gub_branch_on(true, false));
        assert!(
            !gub_branch_on(true, true),
            "forced GUB branching must not bypass the symmetry owner"
        );

        // Three pairwise at-most-one rows form a triangle wider than each seed
        // row, proving that the focused test actually exercises clique growth.
        let mut exact = Model::new();
        let x0 = exact.add_binary_col();
        let x1 = exact.add_binary_col();
        let x2 = exact.add_binary_col();
        exact.add_row(f64::NEG_INFINITY, 1.0, &[(x0, 1.0), (x1, 1.0)]);
        exact.add_row(f64::NEG_INFINITY, 1.0, &[(x0, 1.0), (x2, 1.0)]);
        exact.add_row(f64::NEG_INFINITY, 1.0, &[(x1, 1.0), (x2, 1.0)]);
        let cliques = conflict_cliques(&exact);
        assert_eq!(cliques, vec![vec![0, 1, 2]]);
        for mask in 0u8..8 {
            let point: Vec<BigRational> = (0..3)
                .map(|bit| BigRational::from_integer(i64::from((mask >> bit) & 1).into()))
                .collect();
            if exact.check_point(&point).is_ok() {
                for clique in &cliques {
                    assert!(
                        clique.iter().filter(|&&c| point[c].is_positive()).count() <= 1,
                        "returned support is not at-most-one at {point:?}"
                    );
                }
            }
        }

        // The f64 proxies make 0.1 + 0.2 appear strictly greater than 0.3,
        // while the MPS side store records the true equality. Therefore x0=x1=1
        // is feasible and the first row is NOT an at-most-one certificate. If
        // the classifier consulted only f64, the other two rows would complete
        // the same unsound triangle above.
        assert!(std::hint::black_box(0.1_f64) + 0.2_f64 > 0.3_f64);
        let mut inexact = Model::new();
        let x0 = inexact.add_binary_col();
        let x1 = inexact.add_binary_col();
        let x2 = inexact.add_binary_col();
        let rounded = inexact.add_row(f64::NEG_INFINITY, 0.3, &[(x0, 0.1), (x1, 0.2)]);
        inexact.add_row(f64::NEG_INFINITY, 1.0, &[(x0, 1.0), (x2, 1.0)]);
        inexact.add_row(f64::NEG_INFINITY, 1.0, &[(x1, 1.0), (x2, 1.0)]);
        inexact.record_inexact_row_coeff(rounded, x0.0, BigRational::new(1.into(), 10.into()));
        inexact.record_inexact_row_coeff(rounded, x1.0, BigRational::new(1.into(), 5.into()));
        inexact.record_inexact_row_bound(rounded, false, BigRational::new(3.into(), 10.into()));
        let one = BigRational::from_integer(1.into());
        let zero = BigRational::zero();
        assert!(inexact.check_point(&[one.clone(), one, zero]).is_ok());
        assert!(conflict_cliques(&inexact).is_empty());
    }

    #[test]
    fn branch_hints_break_only_score_ties_between_real_candidates() {
        let cands = [(0usize, 0.25, 3.0), (1usize, 0.50, 3.0)];
        let ranks = branch_hint_ranks(2, &[Col(1), Col(0)]).expect("live ranks");
        let hinted = cands
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, Some(&ranks)))
            .expect("candidate");
        assert_eq!(hinted.0, 1, "earlier hint must win an exact score tie");

        let stronger = [(0usize, 0.25, 4.0), (1usize, 0.50, 3.0)];
        let picked = stronger
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, Some(&ranks)))
            .expect("candidate");
        assert_eq!(
            picked.0, 0,
            "advice must not override a stronger pseudocost score"
        );

        let old_pick = cands
            .iter()
            .max_by(|a, b| a.2.partial_cmp(&b.2).unwrap_or(std::cmp::Ordering::Equal))
            .expect("candidate");
        let no_hint_pick = cands
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, None))
            .expect("candidate");
        assert_eq!(
            no_hint_pick, old_pick,
            "the absent-hint comparator must preserve the historical tie behavior"
        );
    }

    #[test]
    fn hint_telemetry_keeps_the_pre_sort_historical_tie_order() {
        let historical = vec![(0usize, 0.5, 3.0), (1usize, 0.5, 3.0)];
        let live_ranks = branch_hint_ranks(2, &[Col(0), Col(1)]).expect("live ranks");
        let mut live = historical.clone();
        live.sort_by(|a, b| scored_candidate_cmp(b, a, Some(&live_ranks)));

        let hinted = live
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, Some(&live_ranks)))
            .expect("hinted candidate");
        let old_ranks = historical_candidate_tie_ranks(2, &historical);
        let unhinted = live
            .iter()
            .max_by(|a, b| scored_candidate_cmp(a, b, Some(&old_ranks)))
            .expect("historical candidate");

        assert_eq!(hinted.0, 0, "the live hint must win the exact score tie");
        assert_eq!(
            unhinted.0, 1,
            "attribution must recover historical max_by order after live sorting"
        );
        assert!(hint_tie_break_was_final(
            Some((hinted.0, hinted.1)),
            Some((unhinted.0, unhinted.1)),
            Some((hinted.0, hinted.1)),
            false,
        ));
    }

    #[test]
    fn hint_pick_telemetry_counts_only_a_consumed_final_split() {
        let hinted = Some((1usize, 0.5));
        let historical = Some((0usize, 0.5));

        assert!(hint_tie_break_was_final(hinted, historical, hinted, false));
        assert!(!hint_tie_break_was_final(
            hinted, historical, historical, false
        ));
        assert!(!hint_tie_break_was_final(hinted, historical, hinted, true));
        assert!(!hint_tie_break_was_final(hinted, hinted, hinted, false));
    }

    /// The lattice-bottleneck granule (`b-ball`'s shape in miniature): maximize a
    /// continuous `x_o` whose only ceilings are VUB rows `x_o <= x_i`, each `x_i`
    /// pinned to ½ℤ by `2·x_i = Σ binaries`. Granule must be ½; every perturbation
    /// that breaks the shape must decline to `None` (fail-closed).
    #[test]
    fn bottleneck_granularity_detects_half_and_fails_closed() {
        let build = || {
            let mut m = Model::new();
            let xo = m.add_col(0.0, f64::INFINITY); // 0: bottleneck objective column
            let x1 = m.add_col(0.0, f64::INFINITY); // 1: row-1 half-integer variable
            let x2 = m.add_col(0.0, f64::INFINITY); // 2: row-2 half-integer variable
            let c3 = m.add_binary_col(); // 3
            let c4 = m.add_binary_col(); // 4
            let c5 = m.add_binary_col(); // 5
            let c6 = m.add_binary_col(); // 6
            m.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x1, -1.0)]); // x_o <= x_1
            m.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x2, -1.0)]); // x_o <= x_2
            m.add_row(0.0, 0.0, &[(x1, 2.0), (c3, -1.0), (c4, -1.0)]); // 2 x_1 = c3+c4
            m.add_row(0.0, 0.0, &[(x2, 2.0), (c5, -1.0), (c6, -1.0)]); // 2 x_2 = c5+c6
            m.set_objective(&[(xo, -1.0)], Sense::Minimize); // maximize x_o
            m
        };
        assert_eq!(
            bottleneck_granularity(&build()),
            Some(BigRational::new(1.into(), 2.into())),
            "clean bottleneck must yield granule 1/2"
        );
        // A second objective term: the rule no longer applies (x_o is not the sole driver).
        let mut m = build();
        m.set_objective(&[(Col(0), -1.0), (Col(3), 1.0)], Sense::Minimize);
        assert_eq!(
            bottleneck_granularity(&m),
            None,
            "two objective terms decline"
        );
        // A finite NON-lattice box bound on x_o: the corner could be fractional.
        let mut m = build();
        m.set_col_bounds(Col(0), 0.0, 1.7);
        assert_eq!(
            bottleneck_granularity(&m),
            None,
            "fractional box ceiling declines"
        );
        // A partner variable NOT pinned to a lattice (no defining equality): decline.
        // Rebuild x_2 without its 2·x_2 = ... row by giving that row a non-integer coeff.
        let mut m = Model::new();
        let xo = m.add_col(0.0, f64::INFINITY);
        let x1 = m.add_col(0.0, f64::INFINITY);
        m.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x1, -1.0)]);
        m.add_row(0.0, 0.0, &[(x1, 2.5)]); // non-integer coeff: pins no lattice
        m.set_objective(&[(xo, -1.0)], Sense::Minimize);
        assert_eq!(
            bottleneck_granularity(&m),
            None,
            "unpinned partner declines"
        );
        // A finite LATTICE box bound (4 for granule 1/2) is fine — the corner is on ½ℤ.
        let mut m = build();
        m.set_col_bounds(Col(0), 0.0, 4.0);
        assert_eq!(
            bottleneck_granularity(&m),
            Some(BigRational::new(1.into(), 2.into())),
            "integer box ceiling keeps the lattice"
        );
    }

    /// Verdict guard for the arithmetic around the bottleneck proof. The model
    /// sense participates in the driven direction, and every approximate or
    /// overflowing integer operation must decline rather than manufacture a
    /// granule.
    #[test]
    fn bottleneck_granularity_respects_sense_and_exact_arithmetic() {
        let upper_vub = || {
            let mut m = Model::new();
            let xo = m.add_col(0.0, f64::INFINITY);
            let x = m.add_col(0.0, f64::INFINITY);
            let b1 = m.add_binary_col();
            let b2 = m.add_binary_col();
            m.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x, -1.0)]);
            m.add_row(0.0, 0.0, &[(x, 2.0), (b1, -1.0), (b2, -1.0)]);
            m.set_objective(&[(xo, 1.0)], Sense::Maximize);
            m
        };

        assert_eq!(
            bottleneck_granularity(&upper_vub()),
            Some(BigRational::new(1.into(), 2.into())),
            "maximize +x_o drives upward, so upper VUBs govern"
        );

        // Maximize +x_o with only a LOWER VUB and a fractional upper box. The
        // old sign-only rule read the lower shape, checked the lattice lower
        // box, and incorrectly returned 1/2 even though 1.7 is attainable.
        let mut wrong_direction = Model::new();
        let xo = wrong_direction.add_col(0.0, 1.7);
        let x = wrong_direction.add_col(0.0, f64::INFINITY);
        let b1 = wrong_direction.add_binary_col();
        let b2 = wrong_direction.add_binary_col();
        wrong_direction.add_row(f64::NEG_INFINITY, 0.0, &[(x, 1.0), (xo, -1.0)]);
        wrong_direction.add_row(0.0, 0.0, &[(x, 2.0), (b1, -1.0), (b2, -1.0)]);
        wrong_direction.set_objective(&[(xo, 1.0)], Sense::Maximize);
        assert_eq!(
            bottleneck_granularity(&wrong_direction),
            None,
            "rows opposing the objective's true driven direction must decline"
        );

        // The negative-objective Maximize mirror drives x_o downward. A clean
        // lower VUB is valid and has the same half-integer granule.
        let mut lower_vub = Model::new();
        let xo = lower_vub.add_col(f64::NEG_INFINITY, f64::INFINITY);
        let x = lower_vub.add_col(0.0, f64::INFINITY);
        let b1 = lower_vub.add_binary_col();
        let b2 = lower_vub.add_binary_col();
        lower_vub.add_row(f64::NEG_INFINITY, 0.0, &[(x, 1.0), (xo, -1.0)]);
        lower_vub.add_row(0.0, 0.0, &[(x, 2.0), (b1, -1.0), (b2, -1.0)]);
        lower_vub.set_objective(&[(xo, -1.0)], Sense::Maximize);
        assert_eq!(
            bottleneck_granularity(&lower_vub),
            Some(BigRational::new(1.into(), 2.into())),
            "maximize -x_o drives downward, so lower VUBs govern"
        );

        // Conversely, an upper VUB cannot govern that downward objective. The
        // old sign-only rule accepted it and ignored the attainable 1/4 lower
        // box, manufacturing an integer granule.
        let mut negative_wrong_direction = Model::new();
        let xo = negative_wrong_direction.add_col(0.25, f64::INFINITY);
        let y = negative_wrong_direction.add_binary_col();
        negative_wrong_direction.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (y, -1.0)]);
        negative_wrong_direction.set_objective(&[(xo, -1.0)], Sense::Maximize);
        assert_eq!(
            bottleneck_granularity(&negative_wrong_direction),
            None,
            "the negative-objective wrong-direction mirror must decline"
        );

        // Binary floating multiplication is not an exact lattice test:
        // `0.1_f64 * 10.0 == 1.0`, but exact(0.1_f64) * 10 is non-integral.
        let mut rounded_product = Model::new();
        let xo = rounded_product.add_col(0.0, 0.1);
        let x = rounded_product.add_col(0.0, f64::INFINITY);
        let b1 = rounded_product.add_binary_col();
        let b2 = rounded_product.add_binary_col();
        rounded_product.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x, -1.0)]);
        rounded_product.add_row(0.0, 0.0, &[(x, 10.0), (b1, -1.0), (b2, -1.0)]);
        rounded_product.set_objective(&[(xo, 1.0)], Sense::Maximize);
        assert_eq!(
            bottleneck_granularity(&rounded_product),
            None,
            "a rounded f64 product must not certify a box bound as lattice-aligned"
        );

        // lcm(2^63, 3) does not fit u64. Overflow is a clean decline.
        let mut overflow = Model::new();
        let xo = overflow.add_col(0.0, f64::INFINITY);
        let x1 = overflow.add_col(0.0, f64::INFINITY);
        let x2 = overflow.add_col(0.0, f64::INFINITY);
        let b1 = overflow.add_binary_col();
        let b2 = overflow.add_binary_col();
        overflow.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x1, -1.0)]);
        overflow.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x2, -1.0)]);
        overflow.add_row(0.0, 0.0, &[(x1, (1u64 << 63) as f64), (b1, -1.0)]);
        overflow.add_row(0.0, 0.0, &[(x2, 3.0), (b2, -1.0)]);
        overflow.set_objective(&[(xo, 1.0)], Sense::Maximize);
        assert_eq!(
            bottleneck_granularity(&overflow),
            None,
            "LCM overflow declines"
        );

        // `u64::MAX as f64` is actually 2^64 and would saturate an `as u64`
        // cast. It is outside the representable denominator domain.
        let mut saturating = Model::new();
        let xo = saturating.add_col(0.0, f64::INFINITY);
        let x = saturating.add_col(0.0, f64::INFINITY);
        let b = saturating.add_binary_col();
        saturating.add_row(f64::NEG_INFINITY, 0.0, &[(xo, 1.0), (x, -1.0)]);
        saturating.add_row(0.0, 0.0, &[(x, u64::MAX as f64), (b, -1.0)]);
        saturating.set_objective(&[(xo, 1.0)], Sense::Maximize);
        assert_eq!(
            bottleneck_granularity(&saturating),
            None,
            "a saturating float-to-u64 denominator cast must decline"
        );

        // Exact-rational side stores mean the f64 matrix is advisory only.
        let mut inexact = upper_vub();
        inexact.record_inexact_row_coeff(Row(0), 1, BigRational::new((-3).into(), 2.into()));
        assert_eq!(
            bottleneck_granularity(&inexact),
            None,
            "side-store models must not be proved from rounded f64 proxies"
        );
    }

    #[test]
    fn odd_cycle_kill_switch_dominates_opt_in_and_auto_arm() {
        assert!(!odd_cycle_enabled(false, true, true, false));
        assert!(!odd_cycle_enabled(true, false, false, false));
        assert!(odd_cycle_enabled(true, false, true, false));
        assert!(odd_cycle_enabled(true, true, false, false));
        assert!(odd_cycle_enabled(true, true, true, false));
        assert!(!odd_cycle_enabled(true, false, true, true));
        assert!(!odd_cycle_enabled(true, true, false, true));
        assert!(!odd_cycle_enabled(true, true, true, true));
    }

    #[test]
    fn mixing_is_opt_in_and_kill_switch_dominates() {
        assert!(!mixing_enabled(false, false), "mixing defaults off");
        assert!(
            mixing_enabled(true, false),
            "the explicit opt-in enables mixing"
        );
        assert!(!mixing_enabled(false, true));
        assert!(
            !mixing_enabled(true, true),
            "the kill switch must dominate the opt-in"
        );
    }

    /// The root-loop wrapper, not merely the separator's local row scan, owns
    /// the production mixing-family gate. A model with twelve perfectly usable
    /// mixing rows plus one equality row fails the whole-model MIK signature:
    /// the raw separator can cut it, but the production call site must not.
    #[test]
    fn mixing_callsite_requires_the_original_model_mik_gate() {
        let build = |with_equality: bool| {
            let mut m = Model::new();
            let s = m.add_col(0.0, 20.0);
            let y = m.add_int_col(0.0, 3.0);
            for r in 0..12 {
                if r % 2 == 0 {
                    m.add_row(f64::NEG_INFINITY, 1.0, &[(s, -1.0), (y, 3.0)]);
                } else {
                    m.add_row(f64::NEG_INFINITY, 2.0, &[(s, -1.0), (y, 4.0)]);
                }
            }
            if with_equality {
                m.add_row(0.0, 0.0, &[(y, 1.0)]);
            }
            m.set_objective(&[(y, 1.0)], Sense::Minimize);
            (m, vec![1.25, 0.75])
        };

        let (mik, x) = build(false);
        assert!(crate::cuts::is_mixed_integer_knapsack(&mik));
        assert!(
            !separate_mixing_for_root_shape(true, &mik, &mik, &x, mik.num_rows(), 8).is_empty(),
            "the positive call-site control must exercise the mixing separator"
        );
        assert!(
            separate_mixing_for_root_shape(false, &mik, &mik, &x, mik.num_rows(), 8).is_empty(),
            "a valid MIK model must still decline mixing without the explicit opt-in"
        );

        let (not_mik, x) = build(true);
        assert!(!crate::cuts::is_mixed_integer_knapsack(&not_mik));
        assert!(
            !crate::cuts::separate_mixing(&not_mik, &x, not_mik.num_rows(), 8).is_empty(),
            "the local row signature must be non-vacuous in the negative control"
        );
        assert!(
            separate_mixing_for_root_shape(true, &not_mik, &not_mik, &x, not_mik.num_rows(), 8)
                .is_empty(),
            "an equality-row model must not receive opt-in mixing cuts"
        );
    }

    /// BRUTE-FORCE GUARD for the propagation-conflict transfer boxes (license
    /// at `PC_MAX_DEVS`): whatever box `prop_conflict_learn` returns, its
    /// stored claim must hold EXACTLY — with a cutoff, no integer-feasible
    /// point inside the box has objective at or below the cutoff; without
    /// one, the box holds no integer-feasible point at all. Random small
    /// binary knapsack models, random branch-shaped entry boxes, cutoffs
    /// both attainable and deliberately loose; every returned box is checked
    /// by full enumeration. Non-vacuous: the learner must return boxes, and
    /// must MINIMIZE at least once (else the trail is dead code).
    #[test]
    fn prop_conflict_box_never_cuts_a_better_point() {
        let mut seed = 0x9C0_2026_u64;
        let mut rnd = move || {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            (seed >> 33) as i64
        };
        let mut learned = 0usize;
        let mut minimized_ever = 0usize;
        for _case in 0..400 {
            let n = 8usize;
            let mut m = Model::new();
            let cols: Vec<Col> = (0..n).map(|_| m.add_binary_col()).collect();
            let costs: Vec<i64> = (0..n).map(|_| rnd().rem_euclid(9) - 4).collect();
            let obj: Vec<(Col, f64)> = cols
                .iter()
                .zip(&costs)
                .filter(|(_, &v)| v != 0)
                .map(|(&c, &v)| (c, v as f64))
                .collect();
            m.set_objective(&obj, Sense::Minimize);
            let mut rows: Vec<(Vec<i64>, i64, i64)> = Vec::new();
            for _ in 0..3 {
                let a: Vec<i64> = (0..n).map(|_| rnd().rem_euclid(7) - 3).collect();
                if a.iter().all(|&v| v == 0) {
                    continue;
                }
                let s: i64 = a.iter().map(|&v| v.max(0)).sum();
                let lb = -20 + rnd().rem_euclid(10);
                let ub = s - rnd().rem_euclid(1 + s.max(1) / 2);
                let terms: Vec<(Col, f64)> = cols
                    .iter()
                    .zip(&a)
                    .filter(|(_, &v)| v != 0)
                    .map(|(&c, &v)| (c, v as f64))
                    .collect();
                m.add_row(lb as f64, ub as f64, &terms);
                rows.push((a, lb, ub));
            }
            if rows.is_empty() {
                continue;
            }
            let root_lower = vec![0.0f64; n];
            let root_upper = vec![1.0f64; n];
            let col_rows: Vec<Vec<u32>> = {
                let mut m2r: Vec<Vec<u32>> = vec![Vec::new(); n];
                for r in 0..m.num_rows() {
                    let (coeffs, _, _) = m.row(Row(r as u32));
                    for &(c, _) in coeffs {
                        m2r[c as usize].push(r as u32);
                    }
                }
                m2r
            };
            let obj_terms: Vec<(usize, f64)> = costs
                .iter()
                .enumerate()
                .filter(|(_, &v)| v != 0)
                .map(|(j, &v)| (j, v as f64))
                .collect();
            let col_integral = vec![true; n];
            // A branch-shaped entry box: fix a random subset both ways.
            let mut sc = PcScratch::new(n);
            sc.entry_lo.copy_from_slice(&root_lower);
            sc.entry_up.copy_from_slice(&root_upper);
            for j in 0..n {
                match rnd().rem_euclid(3) {
                    0 => {
                        sc.entry_lo[j] = 1.0;
                        sc.entry_up[j] = 1.0;
                    }
                    1 => {
                        sc.entry_lo[j] = 0.0;
                        sc.entry_up[j] = 0.0;
                    }
                    _ => {}
                }
            }
            sc.armed = true;
            // Cutoffs on and off; the cutoff need not come from a genuine
            // incumbent — the stored claim is against the cutoff VALUE.
            for cf in [
                None,
                Some(rnd().rem_euclid(9) as f64 - 6.0),
                Some(-1.0),
                Some(2.0),
            ] {
                // Two-pass impl table exactly as the search mines it, on
                // alternate cases (exercises the table lane of the replay).
                let tab;
                let tab_opt = if cf.is_none() {
                    tab = mine_implications(&m, &col_rows, &root_lower, &root_upper);
                    (!tab.srcs.is_empty()).then_some(&tab)
                } else {
                    None
                };
                let mut minimized = false;
                let Some(lits) = prop_conflict_learn(
                    &m,
                    &col_rows,
                    tab_opt,
                    &obj_terms,
                    &col_integral,
                    cf,
                    &mut sc,
                    &root_lower,
                    &root_upper,
                    &mut minimized,
                ) else {
                    continue;
                };
                learned += 1;
                if minimized {
                    minimized_ever += 1;
                }
                // The box: stored entries where present, root elsewhere.
                let mut blo = root_lower.clone();
                let mut bup = root_upper.clone();
                for &(j, l, u) in &lits {
                    blo[j] = l;
                    bup[j] = u;
                }
                for mask in 0u32..(1 << n) {
                    let x: Vec<f64> = (0..n).map(|j| f64::from(mask >> j & 1)).collect();
                    if (0..n).any(|j| x[j] < blo[j] || x[j] > bup[j]) {
                        continue; // outside the stored box: unclaimed
                    }
                    let feas = rows.iter().all(|(a, lb, ub)| {
                        let act: i64 = (0..n).map(|j| a[j] * (mask >> j & 1) as i64).sum();
                        act >= *lb && act <= *ub
                    });
                    if !feas {
                        continue;
                    }
                    let v: i64 = (0..n).map(|j| costs[j] * (mask >> j & 1) as i64).sum();
                    match cf {
                        // Bound license: nothing at or below the cutoff.
                        Some(c) => assert!(
                            (v as f64) > c,
                            "bound-licensed box cut a point at/below the cutoff: \
                             obj {v} <= cf {c}, lits {lits:?}"
                        ),
                        // Feasibility license: nothing at all.
                        None => panic!(
                            "feasibility-licensed box contains a feasible point \
                             (obj {v}), lits {lits:?}"
                        ),
                    }
                }
            }
        }
        assert!(
            learned > 20 && minimized_ever > 0,
            "vacuous guard: learned={learned} minimized={minimized_ever}"
        );
    }

    /// End-to-end brute-force guard: with propagation-conflict learning
    /// FORCED (plus the implication layer armed from node 0 and the tree as
    /// the finder), random mixed models must still land exactly on their
    /// enumerated optima — the stored boxes must never cut the optimum, and
    /// an infeasible model must stay infeasible. Non-vacuous via
    /// `PC_STORED_TOTAL`: at least one solve must actually store a box.
    #[test]
    fn prop_conflict_learning_preserves_the_optimum() {
        use std::sync::atomic::Ordering::Relaxed;
        let _env_lock = lock_env();
        let stored_before = PC_STORED_TOTAL.load(Relaxed);
        // B38/B39b/B49/B50: every lever rides the per-solve engine profile.
        let nc_opts = SolveOpts::new().with_engine(
            crate::EngineEconomics::new()
                .with_cuts(false)
                .with_heur_share(0.0)
                .with_ng_up(true)
                .with_prop_conflict(true)
                .with_impl_lane(true)
                .with_impl_arm(0),
        );
        let mut seed = 0xC0DE_2026_u64;
        let mut rnd = move || {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            (seed >> 33) as i64
        };
        for _case in 0..8 {
            // Binaries + small general integers, integral objective (the
            // cutoff row needs a granule), knife-edge equality + knapsack
            // rows: deep infeasible/bound-dead subtrees that die on the
            // propagation lanes, not just the LP.
            let nb = 8usize;
            let ni = 3usize;
            let mut m = Model::new();
            let bins: Vec<Col> = (0..nb).map(|_| m.add_binary_col()).collect();
            let ints: Vec<Col> = (0..ni).map(|_| m.add_int_col(0.0, 2.0)).collect();
            let bcost: Vec<i64> = (0..nb).map(|_| rnd().rem_euclid(9) - 4).collect();
            let icost: Vec<i64> = (0..ni).map(|_| rnd().rem_euclid(7) - 3).collect();
            let obj: Vec<(Col, f64)> = bins
                .iter()
                .zip(&bcost)
                .chain(ints.iter().zip(&icost))
                .filter(|(_, &v)| v != 0)
                .map(|(&c, &v)| (c, v as f64))
                .collect();
            m.set_objective(&obj, Sense::Minimize);
            let mut rows: Vec<(Vec<i64>, i64, i64)> = Vec::new();
            for r in 0..3 {
                let a: Vec<i64> = (0..nb + ni).map(|_| 1 + rnd().rem_euclid(19)).collect();
                let smax: i64 = a[..nb].iter().sum::<i64>() + 2 * a[nb..].iter().sum::<i64>();
                let (lb, ub) = if r == 0 {
                    let b = smax / 2 + rnd().rem_euclid(3) - 1;
                    (b, b) // market-split equality at the knife edge
                } else {
                    (0, smax / 2 + rnd().rem_euclid(1 + smax / 4))
                };
                let terms: Vec<(Col, f64)> = bins
                    .iter()
                    .chain(ints.iter())
                    .zip(&a)
                    .map(|(&c, &v)| (c, v as f64))
                    .collect();
                m.add_row(lb as f64, ub as f64, &terms);
                rows.push((a, lb, ub));
            }
            // Brute force: 2^8 * 3^3 assignments.
            let mut best: Option<i64> = None;
            for mask in 0u32..(1 << nb) {
                let mut iv = vec![0i64; ni];
                loop {
                    let ok = rows.iter().all(|(a, lb, ub)| {
                        let act: i64 = (0..nb).map(|j| a[j] * (mask >> j & 1) as i64).sum::<i64>()
                            + (0..ni).map(|k| a[nb + k] * iv[k]).sum::<i64>();
                        act >= *lb && act <= *ub
                    });
                    if ok {
                        let v: i64 = (0..nb)
                            .map(|j| bcost[j] * (mask >> j & 1) as i64)
                            .sum::<i64>()
                            + (0..ni).map(|k| icost[k] * iv[k]).sum::<i64>();
                        best = Some(best.map_or(v, |b: i64| b.min(v)));
                    }
                    // Odometer over the integer columns.
                    let mut k = 0usize;
                    loop {
                        if k == ni {
                            break;
                        }
                        iv[k] += 1;
                        if iv[k] <= 2 {
                            break;
                        }
                        iv[k] = 0;
                        k += 1;
                    }
                    if k == ni {
                        break;
                    }
                }
            }
            let out = solve_milp(&m, &nc_opts);
            match (best, out) {
                (
                    Some(b),
                    Outcome::Optimal {
                        value,
                        model_values,
                        ..
                    },
                ) => {
                    assert_eq!(
                        value,
                        BigRational::from_integer(b.into()),
                        "prop-conflict-forced optimum diverged from brute force"
                    );
                    assert!(m.check_point(&model_values).is_ok());
                }
                (None, Outcome::Infeasible { .. }) => {}
                (want, got) => panic!("brute force {want:?} vs solver {got:?}"),
            }
        }
        // `_guards` restore (drop) at end of scope, still under `_env_lock`.
        assert!(
            PC_STORED_TOTAL.load(Relaxed) > stored_before,
            "guard is vacuous: no solve ever stored a propagation-conflict box"
        );
    }

    /// BRUTE-FORCE LICENSE GUARD for `bound_conflict_box`: every box it
    /// returns claims "no integer-feasible point in here beats the
    /// (learn-time) incumbent" — checked here by full enumeration of the
    /// ROOT box against the row arithmetic, independently of the
    /// certificate: no integer-feasible point inside the returned box (at
    /// its stored bounds, root bounds on unlisted columns) may have an
    /// objective below `best`. Exercised across random mixed models, node
    /// boxes, and incumbents at and below the pruning bound; non-vacuous
    /// for BOTH arms (boxes returned, and boxes genuinely relaxed past the
    /// node's own deviations).
    #[test]
    fn bound_conflict_box_never_cuts_a_better_point() {
        let mut seed = 0xB0DE_2026_u64;
        let mut rnd = move || {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            (seed >> 33) as i64
        };
        let gran = BigRational::from_integer(1.into());
        let mut boxes = 0usize;
        let mut relaxed_boxes = 0usize;
        for _case in 0..40 {
            let nb = 8usize;
            let ni = 3usize;
            let mut m = Model::new();
            let bins: Vec<Col> = (0..nb).map(|_| m.add_binary_col()).collect();
            let ints: Vec<Col> = (0..ni).map(|_| m.add_int_col(0.0, 2.0)).collect();
            let bcost: Vec<i64> = (0..nb).map(|_| rnd().rem_euclid(9) - 4).collect();
            let icost: Vec<i64> = (0..ni).map(|_| rnd().rem_euclid(7) - 3).collect();
            let obj: Vec<(Col, f64)> = bins
                .iter()
                .zip(&bcost)
                .chain(ints.iter().zip(&icost))
                .filter(|(_, &v)| v != 0)
                .map(|(&c, &v)| (c, v as f64))
                .collect();
            m.set_objective(&obj, Sense::Minimize);
            let mut rows: Vec<(Vec<i64>, i64, i64)> = Vec::new();
            for _r in 0..3 {
                let a: Vec<i64> = (0..nb + ni).map(|_| 1 + rnd().rem_euclid(19)).collect();
                let smax: i64 = a[..nb].iter().sum::<i64>() + 2 * a[nb..].iter().sum::<i64>();
                let (lb, ub) = (0, smax / 2 + rnd().rem_euclid(1 + smax / 4));
                let terms: Vec<(Col, f64)> = bins
                    .iter()
                    .chain(ints.iter())
                    .zip(&a)
                    .map(|(&c, &v)| (c, v as f64))
                    .collect();
                m.add_row(lb as f64, ub as f64, &terms);
                rows.push((a, lb, ub));
            }
            let objective: Vec<(u32, f64)> = obj.iter().map(|&(c, v)| (c.0, v)).collect();
            let Some(lp) = FloatLp::from_model(&m, &objective, m.sense()) else {
                continue;
            };
            let root_lower = lp.lower.clone();
            let root_upper = lp.upper.clone();
            // A random branch-shaped node box: fix a few binaries, bound an int.
            let mut node_lower = root_lower.clone();
            let mut node_upper = root_upper.clone();
            for _ in 0..4 {
                let j = rnd().rem_euclid((nb + ni) as i64) as usize;
                if j < nb {
                    let v = rnd().rem_euclid(2) as f64;
                    node_lower[j] = v;
                    node_upper[j] = v;
                } else if rnd().rem_euclid(2) == 0 {
                    node_lower[j] = 1.0 + rnd().rem_euclid(2) as f64;
                } else {
                    node_upper[j] = rnd().rem_euclid(2) as f64;
                }
                if node_lower[j] > node_upper[j] {
                    node_lower[j] = node_upper[j];
                }
            }
            let cand = lp.solve_bounded(&node_lower, &node_upper, None, None);
            if cand.status != SimplexStatus::Optimal {
                continue;
            }
            for k in 0..3i64 {
                // Fresh certificate per incumbent: `bound_conflict_box`
                // consumes the rc buffer as scratch for its final check.
                let mut rc = vec![(0.0f64, 0.0f64); lp.n];
                let Some(l) = safe_bound(&lp, &cand.duals, &node_lower, &node_upper, &mut rc)
                else {
                    continue;
                };
                let rounded = round_up_to(&exact(l).expect("finite bound"), &gran);
                // An incumbent at (k=0) and below the pruning bound: the
                // node prunes in every case, with growing relaxation slack.
                let best = &rounded - BigRational::from_integer(k.into());
                let mut relaxed_any = false;
                let Some(lits) = bound_conflict_box(
                    &lp,
                    &cand.duals,
                    &node_lower,
                    &node_upper,
                    &root_lower,
                    &root_upper,
                    &best,
                    Some(&gran),
                    &mut rc,
                    &mut relaxed_any,
                ) else {
                    continue;
                };
                boxes += 1;
                if relaxed_any {
                    relaxed_boxes += 1;
                }
                // Brute force over the ROOT box: any integer-feasible point
                // inside the returned box must be no better than `best`.
                let in_box = |x: &[i64]| {
                    lits.iter()
                        .all(|&(j, lo, up)| (x[j] as f64) >= lo && (x[j] as f64) <= up)
                };
                for mask in 0u32..(1 << nb) {
                    let mut iv = vec![0i64; ni];
                    loop {
                        let x: Vec<i64> = (0..nb)
                            .map(|j| (mask >> j & 1) as i64)
                            .chain(iv.iter().copied())
                            .collect();
                        let feasible = rows.iter().all(|(a, lb, ub)| {
                            let act: i64 = a.iter().zip(&x).map(|(&c, &v)| c * v).sum();
                            act >= *lb && act <= *ub
                        });
                        if feasible && in_box(&x) {
                            let v: i64 = bcost
                                .iter()
                                .chain(icost.iter())
                                .zip(&x)
                                .map(|(&c, &v)| c * v)
                                .sum();
                            assert!(
                                BigRational::from_integer(v.into()) >= best,
                                "bound conflict box cut a BETTER point: obj {v} < best {best} \
                                 (k={k}, relaxed={relaxed_any}, lits={lits:?})"
                            );
                        }
                        let mut c = 0usize;
                        loop {
                            if c == ni {
                                break;
                            }
                            iv[c] += 1;
                            if iv[c] <= 2 {
                                break;
                            }
                            iv[c] = 0;
                            c += 1;
                        }
                        if c == ni {
                            break;
                        }
                    }
                }
            }
        }
        assert!(boxes > 0, "guard is vacuous: no box was ever returned");
        assert!(
            relaxed_boxes > 0,
            "guard is vacuous for the greedy: no box was ever relaxed past the node's deviations"
        );
    }

    /// End-to-end brute-force guard: with LP-bound conflict learning FORCED
